package cn.lili.modules.community.p0.stage3;
import cn.lili.modules.community.p0.stage2.Stage2Settings;import cn.lili.modules.community.p0.support.Stage1Db;import org.junit.jupiter.api.Test;import org.springframework.mock.env.MockEnvironment;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;
class Stage3ResourceScopeTest {
 @Test void wrongModeDoesNotEvenQueryAResource(){var db=mock(Stage1Db.class);assertThrows(IllegalStateException.class,()->Stage3ResourceScope.verify(db,new Stage2Settings(),new MockEnvironment()));verifyNoInteractions(db);}
 @Test void protectedUuidAndWrongApplicationAccountAreRejectedBeforeFilesystemUse(){var db=mock(Stage1Db.class);var s=new Stage2Settings();s.setEnabled(true);s.setStage3ResourceMode(true);s.setDatabase("dgl_p0_s3");s.setMysqlUuid("043ca7b1-d2d6-11f1-889b-7af81f86d1ff");var env=new MockEnvironment().withProperty("p0.stage3.enabled","true");when(db.required(anyString())).thenReturn(map("uuid",s.getMysqlUuid(),"database_name","dgl_p0_s3","account","s3_app@%"));assertThrows(IllegalStateException.class,()->Stage3ResourceScope.verify(db,s,env));s.setMysqlUuid("UNIT_NEW_UUID");when(db.required(anyString())).thenReturn(map("uuid","UNIT_NEW_UUID","database_name","dgl_p0_s3","account","s2_app@%"));assertThrows(IllegalStateException.class,()->Stage3ResourceScope.verify(db,s,env));}
}
